const $=id=>document.getElementById(id), canvas=$('city');let state=initial(),selected=0,before=false,view,sound=false,audioCtx,recording=null,recordTimer,dedication='',creator='',landmark=null,incomingGift=false,resultBlob=null,storyTimer=null,typingTimer=null,storyCleanup=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function say(t){$('notice').textContent=t}function modal(html){$('modal-content').innerHTML=html;$('modal').showModal()}$('close').onclick=()=>{stopLetter();$('modal').close()};$('modal').addEventListener('close',stopLetter);$('modal').addEventListener('click',e=>{if(e.target===$('modal'))$('modal').close()});
const voices={forest:{quote:'Today I heard birds on my walk to school. Mum says this used to be a factory.',name:'A child of 2058',tag:'A place to breathe'},solar:{quote:'The lights stayed on through the storm. We made the power right here, together.',name:'A neighbour of 2058',tag:'A future powered together'},homes:{quote:'Grandad lives across the courtyard. Every evening, we meet under the trees.',name:'A family of 2058',tag:'A place to belong'},wetland:{quote:'The water rose, but the reeds held. The city gave the sea room to breathe.',name:'A coastal resident of 2058',tag:'A coast that cares for us'}};
function update(){let n=state.plots.filter(Boolean).length;$('budget').textContent=state.budget+' credits';$('legacy').innerHTML=score(state)+'<span>/100</span>';$('year').textContent=state.year;$('turn').textContent=state.ended?'Your gift is complete':(2058-state.year)+' years remaining';$('restored').textContent=n+' / 6 restored';$('stats').innerHTML=['Nature','Clean energy','Wellbeing','Resilience'].map((v,i)=>`<div class="stat"><label>${v} <b>${state.stats[i]}%</b></label><div class="bar"><i style="width:${state.stats[i]}%"></i></div></div>`).join('');$('districts').innerHTML=districts.map((d,i)=>`<button class="${i===selected?'active ':''}${state.plots[i]?'done':''}" aria-pressed="${i===selected}" aria-label="${d.name}${state.plots[i]?', restored':''}" data-district="${i}">${String(i+1).padStart(2,'0')}</button>`).join('');document.querySelectorAll('[data-district]').forEach(b=>b.onclick=()=>select(+b.dataset.district));$('district-tag').textContent='DISTRICT '+String(selected+1).padStart(2,'0');$('district-name').textContent=districts[selected].name;$('district-desc').textContent=state.plots[selected]?'Restored with '+projects.find(p=>p.id===state.plots[selected]).name.toLowerCase()+'. A piece of tomorrow, already here.':districts[selected].desc;$('projects').innerHTML=projects.map(p=>`<button class="project" data-project="${p.id}" ${state.ended||state.plots[selected]||state.budget<p.cost?'disabled':''}><strong>${p.name}</strong><span>${p.cost} credits</span><small>${p.hint}</small><em>${bonusText(p.id)}</em></button>`).join('');document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>actBuild(selected,b.dataset.project));$('journal').textContent=state.log[0];updateStory();$('advance').disabled=state.ended;$('world-caption').textContent=before?'The city you inherited in 2050.':dedication?'A city for '+dedication+'. A letter shaped by you.':n===6?'Every district has a future.':n>2?'Life is finding its way back.':'Your choices become a letter to someone you love.';}
function select(i){selected=i;update();rebuild();}function actBuild(i,id){try{build(state,i,id);selected=i;before=false;$('compare').setAttribute('aria-pressed','false');update();rebuild();tone();say(projects.find(p=>p.id===id).name+' built. Choose another district, or advance a year.');return getState()}catch(e){say(e.message);throw e}}
function next(){advance(state);update();say(state.log[0]);tone(220);if(state.ended)playStory();else if(state.year===2053||state.year===2056)showEvent();return getState()}
function ending(animate=false){const win=isWin(state),letter=letterFor(state,dedication,landmark);resultBlob=null;modal(`<span class="eyebrow"><span id="letter-sender"></span> · 2058</span><h2 id="letter-to"></h2><div class="letter-body">${letter.paragraphs.map(()=>'<p></p>').join('')}</div><details class="legacy-details"><summary>${win?'A thriving future':'An unfinished future'} · Legacy ${score(state)}/100</summary><p>${state.plots.filter(Boolean).length}/6 districts restored. Nature ${state.stats[0]}, energy ${state.stats[1]}, wellbeing ${state.stats[2]}, resilience ${state.stats[3]}. A thriving future requires 70 legacy, every vital at least 50 and all six districts restored.</p></details><div class="letter-controls"><button id="read-letter">Read aloud</button><button id="show-letter">Show full letter</button><button id="replay-city">Replay the years</button></div><button class="primary" id="share-gift">${incomingGift?"Pass on this city":"Send this city"}</button><button class="copy-link" id="copy-city-link">Copy gift link</button><p class="gift-privacy">The link includes the names and this city. Anyone with the link can open it.</p><p id="share-status" role="status"></p><div class="ending-actions"><button id="save-postcard">Save postcard</button><button id="save-letter">Save letter</button><button id="again">${incomingGift?"Build a gift for someone else":"Build another future"}</button></div>`);$('letter-sender').textContent=incomingGift?'A GIFT FROM '+(creator||'SOMEONE WHO CARES'):'YOUR LETTER';$('letter-to').textContent='Dear '+letter.to+',';showFullLetter(letter);$('again').textContent=incomingGift?'Build one for '+(creator||'someone who cares'):'Build another future';$('again').onclick=incomingGift?giftBack:reset;$('save-letter').onclick=saveLetter;$('save-postcard').onclick=savePostcard;$('share-gift').onclick=shareGift;$('copy-city-link').onclick=copyCityLink;$('read-letter').onclick=()=>readLetter(letter);$('read-letter').disabled=!window.speechSynthesis||!window.SpeechSynthesisUtterance;$('show-letter').onclick=()=>{clearTimeout(typingTimer);showFullLetter(letter)};$('replay-city').onclick=()=>playStory();if(animate&&!reduced){$('show-letter').hidden=false;typeLetter(letter);}else $('show-letter').hidden=true;makePostcard().then(b=>{resultBlob=b}).catch(()=>{});}

function reset(){cancelStory();stopLetter();if(incomingGift){dedication='';creator='';$('dedication').value='';$('creator').value='';$('dedication-status').textContent='Choose someone to build a future for.';}incomingGift=false;$('dedication').disabled=false;$('creator').disabled=false;$('dedication-form').querySelector('button').disabled=false;if(window.location?.hash?.startsWith('#gift='))window.history.replaceState(null,'',window.location.pathname+window.location.search);state=initial();landmark=null;view?.setLandmark(null);updateLandmarkChoice();selected=0;before=false;resultBlob=null;$('compare').setAttribute('aria-pressed','false');if($('modal').open)$('modal').close();update();rebuild();say('A new city, a new chance.');}
$('advance').onclick=next;$('restart').onclick=()=>{modal('<h2>Build a new future?</h2><p>This starts a fresh city and clears your current run.</p><button class="primary" id="confirm-reset">Start new city</button>');$('confirm-reset').onclick=reset};$('guide').onclick=()=>modal('<span class="eyebrow">EIGHT YEARS. ONE SHARED FUTURE.</span><h2>Give tomorrow a place to live.</h2><ol><li>Select a district in the world or use the numbered buttons.</li><li>Build one project per district. Each choice changes four city vitals.</li><li>Advance a year to collect 24 credits. Prepare for a storm in 2053 and a heatwave in 2056.</li><li>Placement matters: coastal wetlands gain +6 resilience, Foundry Hill solar gains +6 energy, and each neighbouring forest–housing pair adds +4 wellbeing.</li><li>By 2058, restore all six districts, reach a legacy score of 70, and keep every vital at 50 or above. The score is the average of the four vitals.</li></ol><p>Drag the city to rotate. Pinch with two fingers, scroll, or use the + / − buttons to zoom. Reset camera restores the original view. Progress lasts for this session. This is a fictional strategy game, not an environmental model.</p>');$('rotate').onclick=()=>view?.rotate();$('zoom-in').onclick=()=>view?.zoomBy(.85);$('zoom-out').onclick=()=>view?.zoomBy(1/.85);$('compare').onclick=()=>{before=!before;$('compare').setAttribute('aria-pressed',String(before));update();rebuild()};
const soundscape=createSoundscape({host:window,getRestored:()=>state.plots.filter(Boolean).length,isHidden:()=>document.hidden});
$('sound').onclick=async()=>{$('sound').disabled=true;sound=await soundscape.setEnabled(!sound);$('sound').disabled=false;audioCtx=soundscape.context;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',String(sound));if(sound)tone();else if(!audioCtx)say('Sound is unavailable on this device. Your city still works.');};
document.addEventListener('visibilitychange',()=>soundscape.visibility());window.addEventListener('pagehide',()=>soundscape.dispose());
function tone(f=440){if(!sound||!audioCtx||audioCtx.state!=='running')return;try{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(.025,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.4);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.4);o.onended=()=>{o.disconnect();g.disconnect();};}catch{}}
function rebuild(){view?.rebuild(state,selected,before)}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000)}
$('board').onclick=()=>{if(!view)return say('3D rendering is required to export the asset board.');const board=document.createElement('canvas');board.width=1800;board.height=1350;const c=board.getContext('2d');c.fillStyle='#0b171c';c.fillRect(0,0,1800,1350);c.fillStyle='#c2f970';c.font='bold 44px Arial';c.fillText('FUTURE CITY / VISUAL ASSET BOARD',60,75);c.fillStyle='#afc6ca';c.font='24px Arial';c.fillText('Build a city. Leave a letter. · '+(landmarkFor(landmark)?.name||'Original procedural island')+' · '+(view.landmarkInfo().source==='glb'?'GLB landmark':'Procedural geometry'),60,120);const stages=[{title:'01 / THE WORLD WE INHERIT',plots:Array(6).fill(null)},{title:'02 / THE WORLD WE LEAVE',plots:['forest','solar','wetland','homes','solar','forest']},{title:'03 / PLACES TO BELONG',plots:Array(6).fill('homes')},{title:'04 / ROOM FOR NATURE',plots:['forest','wetland','forest','wetland','forest','wetland']}];stages.forEach((s,i)=>{const img=view.capture({...initial(),plots:s.plots},false,.66+(i===2?.8:0));const x=60+(i%2)*855,y=165+Math.floor(i/2)*575;const scale=Math.min(825/img.width,495/img.height),w=img.width*scale,h=img.height*scale;c.fillStyle='#123641';c.fillRect(x,y,825,495);c.drawImage(img,x+(825-w)/2,y+(495-h)/2,w,h);c.fillStyle='#edf6f5';c.font='23px Arial';c.fillText(s.title,x,y+533)});board.toBlob(b=>{if(b)download(b,'Future-City-Asset-Board.png')});say('Asset board downloaded: four views from the actual game.');};
$('record').onclick=async()=>{if(recording){recording.stop();return}if(!navigator.mediaDevices?.getDisplayMedia||!window.MediaRecorder){say('Recording is not supported here. Use your device screen recorder while playing.');return}try{const stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:false});const mime=['video/webm;codecs=vp9','video/webm','video/mp4'].find(x=>MediaRecorder.isTypeSupported(x));const chunks=[];const rec=new MediaRecorder(stream,mime?{mimeType:mime}:{});recording=rec;rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=()=>{clearTimeout(recordTimer);const type=rec.mimeType;download(new Blob(chunks,{type}),`Future-City-Walkthrough.${type.includes('mp4')?'mp4':'webm'}`);stream.getTracks().forEach(t=>t.stop());recording=null;$('record').textContent='Record my playthrough';say('Walkthrough downloaded. Review it before submitting.');};stream.getVideoTracks()[0].onended=()=>{if(rec.state==='recording')rec.stop()};rec.start();$('record').textContent='Stop & save recording';say('Recording. Play your city, then press Stop & save recording.');recordTimer=setTimeout(()=>{if(rec.state==='recording')rec.stop()},180000)}catch(e){say('Recording did not start. You can use your device screen recorder instead.')}};
function getState(){return {year:state.year,budget:state.budget,legacy:score(state),stats:[...state.stats],districts:districts.map((d,i)=>({id:i+1,name:d.name,project:state.plots[i]})),ended:state.ended}}
if(document.modelContext?.registerTool){const controller=new AbortController();for(const tool of [{name:'read_future_city',description:'Read city vitals, budget, year and district projects.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>getState()},{name:'restore_future_city_district',description:'Spend in-game credits to permanently restore a district in the current game.',inputSchema:{type:'object',properties:{district:{type:'integer',minimum:1,maximum:6},project:{type:'string',enum:projects.map(p=>p.id)}},required:['district','project'],additionalProperties:false},execute:v=>{if(!v||!Number.isInteger(v.district))throw Error('district must be an integer');return actBuild(v.district-1,v.project)}},{name:'advance_future_city_year',description:'Advance one game year, collect funding and resolve any environmental event.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:()=>next()}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>controller.abort(),{once:true})}
