let lostView=null;canvas.addEventListener('webglcontextlost',event=>{event.preventDefault();lostView=view;view=undefined;showGraphicsFallback();});canvas.addEventListener('webglcontextrestored',()=>{if(lostView){view=lostView;lostView=null;view.setLandmark(landmark);rebuild();$('webgl-fallback').hidden=true;document.querySelector('.world').classList.remove('no-webgl');}});
