$('creator').addEventListener('input',()=>{creator=cleanName($('creator').value)});
function stopLetter(){clearTimeout(typingTimer);window.speechSynthesis?.cancel();const button=$('read-letter');if(button)button.textContent='Read aloud';}
function showFullLetter(letter){const p=document.querySelectorAll('.letter-body p');p.forEach((node,i)=>node.textContent=letter.paragraphs[i]);const b=$('show-letter');if(b)b.hidden=true;}
function typeLetter(letter){clearTimeout(typingTimer);const nodes=[...document.querySelectorAll('.letter-body p')];nodes.forEach(p=>p.textContent='');let para=0,offset=0;function tick(){if(!$('modal').open)return;if(para>=nodes.length){$('show-letter').hidden=true;return;}offset+=9;nodes[para].textContent=letter.paragraphs[para].slice(0,offset);if(offset>=letter.paragraphs[para].length){para++;offset=0;}typingTimer=setTimeout(tick,25);}tick();}
function readLetter(letter){if(!window.speechSynthesis||!window.SpeechSynthesisUtterance)return;const button=$('read-letter');if(window.speechSynthesis.speaking){window.speechSynthesis.cancel();button.textContent='Read aloud';return;}showFullLetter(letter);clearTimeout(typingTimer);const utterance=new window.SpeechSynthesisUtterance(`Dear ${letter.to}. ${letter.paragraphs.join(' ')}${creator?' From '+creator+'.':''}`);utterance.lang='en-AU';utterance.rate=.92;utterance.onend=()=>{if($('read-letter'))$('read-letter').textContent='Read aloud'};utterance.onerror=()=>{if($('read-letter'))$('read-letter').textContent='Read aloud';if($('share-status'))$('share-status').textContent='Narration is unavailable on this device. You can still read or save the letter.'};button.textContent='Stop narration';window.speechSynthesis.speak(utterance);}
function cancelStory(){clearTimeout(storyTimer);if(storyCleanup){const cleanup=storyCleanup;storyCleanup=null;cleanup();}}
function playStory(arrival=false){cancelStory();stopLetter();if($('modal').open)$('modal').close();if(!view||reduced){view?.setNight(true);view?.focusLandmark();ending(false);return;}const wasCinema=document.body.classList.contains('cinematic'),savedBefore=before;before=false;document.body.classList.add('cinematic','story-mode');view.setCinema(true);view.setNight(false);view.flyTo(-.65,27);const overlay=document.createElement('section');overlay.id='story-overlay';overlay.innerHTML=`<span class="eyebrow"><span id="story-sender"></span></span><strong id="story-year">${arrival?'2058':'2050'}</strong><p id="story-line"></p><button id="story-skip">Read the letter now</button>`;document.body.append(overlay);$('story-sender').textContent=arrival?(creator||'Someone')+' built this island for you':'THE YEARS THAT MADE YOUR GIFT';$('story-line').textContent=arrival?'A city for '+(dedication||'you')+'.':'Every choice becomes part of the letter.';const frames=arrival?[structuredClone(state)]:giftFrames(state);let index=0;storyCleanup=()=>{overlay.remove();document.body.classList.remove('story-mode');if(!wasCinema)document.body.classList.remove('cinematic');view.setCinema(wasCinema);before=savedBefore;rebuild();};function finish(animate=true){cancelStory();view.setNight(true);view.focusLandmark();$('night').textContent='Daylight';$('night').setAttribute('aria-pressed','true');ending(animate);}$('story-skip').onclick=()=>finish(false);function step(){const frame=frames[Math.min(index,frames.length-1)];view.rebuild(frame,-1,false);$('story-year').textContent=frame.year;const count=frame.plots.filter(Boolean).length;$('story-line').textContent=arrival?'This island was built for '+(dedication||'you')+'.':count===0?'An island waiting for someone to care.':count+'/6 districts restored. A future taking shape.';view.flyTo(-.65+index*.16,24);if(index>=frames.length-1){view.setNight(true);if(arrival){storyTimer=setTimeout(()=>{view.focusLandmark();storyTimer=setTimeout(finish,1800);},4700);}else{view.focusLandmark();storyTimer=setTimeout(finish,1500);}return;}index++;storyTimer=setTimeout(step,Math.max(300,8500/frames.length));}step();}
function updateLandmarkChoice(){const chosen=landmarkFor(landmark);$('landmark-summary').textContent=chosen?chosen.love+' · '+chosen.name:'A place for what they love';$('choose-landmark').textContent=chosen?'Change landmark':'Choose a landmark';$('choose-landmark').disabled=incomingGift;}
function chooseLandmark(){if(incomingGift)return;modal('<span class="eyebrow">A PLACE JUST FOR THEM</span><h2>What do they love?</h2><p>One small landmark makes this island theirs. It also becomes a line in their letter.</p><div class="landmark-options"></div><button class="copy-link" id="skip-landmark">Keep building</button>');const container=document.querySelector('.landmark-options');for(const item of LANDMARKS){const b=document.createElement('button');b.type='button';b.textContent=item.love+' — '+item.name;b.setAttribute('aria-pressed',String(landmark===item.id));b.onclick=()=>{landmark=item.id;view?.setLandmark(landmark);resultBlob=null;updateLandmarkChoice();$('modal').close();say(item.name+' is at the heart of your gift.');};container.append(b);}$('skip-landmark').onclick=()=>$('modal').close();}
$('choose-landmark').onclick=chooseLandmark;
function loadGift(){const fragment=window.location?.hash;if(!fragment?.startsWith('#gift='))return;let gift;try{gift=decodeGift(fragment)}catch(e){modal('<span class="eyebrow">GIFT LINK</span><h2>This gift link looks damaged — build your own?</h2><p>We could not safely reconstruct this island. You can ask the sender for a new link, or make a new gift.</p><button class="primary" id="gift-start-new">Build your own</button>');$('gift-start-new').onclick=reset;return;}cancelStory();stopLetter();state=gift.state;dedication=gift.to;creator=gift.from;landmark=gift.landmark;view?.setLandmark(landmark);incomingGift=true;updateLandmarkChoice();selected=0;before=false;$('dedication').value=dedication;$('creator').value=creator;$('dedication').disabled=true;$('creator').disabled=true;$('dedication-form').querySelector('button').disabled=true;$('dedication-status').textContent='This is the city you received. You can explore it or build a new gift.';update();rebuild();modal(`<span class="eyebrow" id="gift-from"></span><h2 id="gift-arrival-title"></h2><p id="gift-arrival-description"></p><button class="primary" id="open-city-gift">Open your city</button><button class="copy-link" id="gift-read-now">Read the letter</button>`);$('gift-from').textContent='A gift from '+(creator||'someone who cares');$('gift-arrival-title').textContent=(creator||'Someone')+' built this island for you.';$('gift-arrival-description').textContent=(dedication?'For '+dedication+'. ':'')+'Six districts, eight years of choices, and a letter from 2058.';$('open-city-gift').onclick=()=>playStory(true);$('gift-read-now').onclick=()=>ending(false);}
