let submissionURLs=[];
$('submission-images').onclick=async()=>{
 if(!view)return say('3D graphics are needed to capture submission images. Open this page in a WebGL-enabled browser.');
 cancelStory();stopLetter();
 const activeView=view,saved=activeView.getPresentation(),savedLandmark=landmark;
 const id=landmark||'books',files=[];
 modal('<h2>Preparing your submission images…</h2><p>Capturing a complete example city with your chosen landmark. Your game will be restored afterwards. Keep this tab open.</p>');
 $('close').disabled=true;
 const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
 const paint=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
 const png=c=>new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('Image export was unavailable.')),'image/png'));
 let warning='';
 try{
  activeView.setCinema(false);activeView.resetCamera();activeView.setLandmark(id);
  for(let i=0;i<100&&activeView.landmarkInfo().source!=='glb';i++)await wait(100);
  if(activeView.landmarkInfo().source!=='glb')warning='The Tripo model did not load; these images show the procedural fallback. Retry before using them to demonstrate Tripo.';
  await wait(750);
  const complete=initial();build(complete,0,'forest');build(complete,1,'solar');build(complete,2,'wetland');advance(complete);build(complete,3,'homes');advance(complete);advance(complete);build(complete,4,'solar');advance(complete);build(complete,5,'forest');while(!complete.ended)advance(complete);
  const shots=[['01-island-before.png',initial(),false,.66,24],['02-restored-day.png',complete,false,.66,24],['03-restored-night.png',complete,true,.66,24],['04-gift-landmark.png',complete,true,.5,13]];
  let nightImage;
  for(const [name,city,night,angle,distance] of shots){
   if(view!==activeView)throw Error('3D graphics were interrupted. Please reload and retry.');
   activeView.rebuild(city,-1,false);activeView.setNight(night);await paint();
   const image=activeView.capture(city,false,angle,{width:1920,height:1080,zoom:distance});
   if(name==='03-restored-night.png')nightImage=image;
   files.push({name,blob:await png(image)});
  }
  const cover=document.createElement('canvas');cover.width=1920;cover.height=1080;const ctx=cover.getContext('2d');ctx.drawImage(nightImage,0,0);
  const shade=ctx.createLinearGradient(0,0,0,260);shade.addColorStop(0,'#081b25f5');shade.addColorStop(1,'#081b2500');ctx.fillStyle=shade;ctx.fillRect(0,0,1920,260);
  ctx.fillStyle='#eff4e3';ctx.font='bold 66px Georgia';ctx.fillText('FUTURE CITY',65,100);ctx.font='36px Georgia';ctx.fillText('Build a city. Leave a letter.',65,160);
  ctx.fillStyle='#081b25dc';ctx.fillRect(0,1000,1920,80);ctx.fillStyle='#c6fb7b';ctx.font='25px Arial';ctx.fillText('A playable world as a gift · '+landmarkFor(id).name,65,1050);
  files.unshift({name:'00-cover.png',blob:await png(cover)});
  const zip=await mediaZip(files);
  for(const url of submissionURLs)URL.revokeObjectURL(url);submissionURLs=[];
  modal('<h2>Your submission images are ready.</h2><p>Use 00-cover.png as the cover. Upload the four numbered images separately to the visual asset board. All are 1920 × 1080 PNGs captured from the game.</p><p id="media-warning" role="status"></p><div id="media-downloads" class="media-downloads"></div><p>You can download everything as a ZIP, or save each image separately. Open the images and check them before uploading.</p>');
  $('media-warning').textContent=warning;
  for(const file of [{name:'Future-City-Submission-Images.zip',blob:zip},...files]){const a=document.createElement('a');a.href=URL.createObjectURL(file.blob);submissionURLs.push(a.href);a.download=file.name;a.textContent=file.name;$('media-downloads').append(a);}
 }catch(error){modal('<h2>Image export could not finish.</h2><p id="media-error"></p><p>Your game has been restored. Try again, or capture screenshots using your device.</p>');$('media-error').textContent=error.message;}
 finally{activeView.setLandmark(savedLandmark);activeView.restorePresentation(saved);rebuild();$('close').disabled=false;}
};
